function fn_searchReqInf() {
	var uri = "/prelistingKosdaq.do?SCREN_ID="+vScrenID+"&SCREN_PROCES_TP_CD="+SCREN_PROCS_TP_CD_01+"&method=searchCmtdelibReqInf" +
			  "&inputMessageId=PRELISTING_KOSDAQ_CMTDELIB_REQINF_INOUT" +
			  "&outputMessageId=PRELISTING_KOSDAQ_CMTDELIB_REQINF_INOUT" +
			  "&BZ_PROCS_NO=" + dts_Cmt.NameString(dts_Cmt.RowPosition, "BZ_PROCS_NO");

	dts_ReqInf.DataID = encodeURI(uri);
	dts_ReqInf.reset();
}
*/

scwin.fn_search = function() {
    // 발행기관코드가 키값이다.	

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=PRELISTING_KOSPI_CMTDELIB_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstinvstg.prelminvstg.select.cmtdelib.condition" + "&{P}param01=" + scwin.strKeyLstBzProcsNo;
    dts_Cmt.DataID = encodeURI(url);
    dts_Cmt.reset();
};


/*
function fn_search() { // 발행기관코드가 키값이다.
	var uri = "/prelistingKosdaq.do?SCREN_ID="+vScrenID+"&SCREN_PROCES_TP_CD="+SCREN_PROCS_TP_CD_01+"&method=listCmtdelib" +
			  "&inputMessageId=PRELISTING_KOSDAQ_CMTDELIB_REQINF_INOUT" +
			  "&outputMessageId=PRELISTING_KOSDAQ_CMTDELIB_REQINF_INOUT" +
			  "&ISUR_CD=" + strKeyIsurCd;

	dts_Cmt.DataID = encodeURI(uri);
	dts_Cmt.reset();
}
*/

// search function end
scwin.fn_save = function(jobType) {
    {
        /*
        var s = "";
        for (i = 1; i <= dts_ReqInf.CountColumn; i++) { s = s + "\n" +  dts_ReqInf.ColumnID(i) + "," + dts_ReqInf.ColumnString(1, i); }
        log.Text = log.Text + "\n" + s + "\n" + dts_ReqInf.Text;

        s = "";
        for (i = 1; i <= dts_Cmt.CountColumn; i++) { s = s + "\n" +  dts_Cmt.ColumnID(i) + "," + dts_Cmt.ColumnString(1, i); }
        log.Text = log.Text + "\n" + s + "\n" + dts_Cmt.Text;
        */
    }

    /*
    if (js_dep_cd.substring(0, 2) !== '33') { //코스닥 심사팀
    	alert("해당 부서만 접수가 가능합니다."); return;
    }
    */

    //2009.05.12 위원회일/철회일 필수 체크
    if (med_ComiteDd.getValue() == "") {
        $c.win.alert("위원회일/철회일을 입력하여 주세요");
        med_ComiteDd.focus();
        return false;
    }
    if ($c.stf.getObjectValue(rdo_COMITE_EXEC_YN) == "") {
        $c.win.alert("위원회실시여부를 선택하세요.");
        rdo_COMITE_EXEC_YN.focus();
        return false;
    }
    if (dts_Cmt.getTotalRow() > 1) {
        var tDunCheckDate = dts_Cmt.getCellData(1, "COMITE_DD");
        var tTotalCount = 0;
        for (var i = 2; i <= dts_Cmt.getTotalRow(); i++) {
            if (tDunCheckDate == dts_Cmt.getCellData(i, "COMITE_DD")) {
                tTotalCount++;
            }
        }
        if (tTotalCount > 0) {
            $c.win.alert("동일한 위원회일/철회일이 존재합니다.\n위원회일/철회일을 확인하세요.");
            med_ComiteDd.focus();
            return false;
        }
    }
    var check = scwin.fn_fileYnCheck();
    var vScrenProcTpCd;
    if (jobType == "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (jobType == "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (jobType == "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    if ($c.cp.isModified(dts_Cmt) || $c.cp.isModified(dts_ReqInf)) {
        // dts_ReqInf의 UseChangeInfo를 false로 지정하여 무조건 insert상태로 서버로 전송됨.
        dts_ReqInf.setCellData(1, "LST_COMITE_RSLT_SAVE_EMP_NO", scwin.fn_getUserId());
        tr_Save.Action = "/prelistingKosdaq.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveCmtdelib";
        tr_Save.KeyName = "toinb_dataid4";
        tr_Save.KeyValue = "JSP(I:pInpReqInf=dts_ReqInf,I:pInpCmt=dts_Cmt ,I:pFile=dts_fileList)";
        tr_Save.Post();
    } else if (!$c.cp.isModified(dts_Cmt) && !$c.cp.isModified(dts_ReqInf) && check == "Y") {
        scwin.fn_fileInsert();
    } else {
        $c.win.alert(scwin.MGS_NO_UPDT);
    }
};


//파일첨부 삭제 여부
scwin.fn_fileYnCheck = function() {
    for (i = 1; i <= dts_fileList.getTotalRow(); i++) {
        if (dts_fileList.getCellData(i, "fileInfo") != "") {
            scwin.file_flag = "Y";
        }
    }
    return scwin.file_flag;
};


//첨부파일 저장
scwin.fn_fileInsert = function() {
    if ($c.cp.isModified(dts_fileList)) {
        //alert(dts_fileList.Text);
        tr_File.Action = "/prelistingKosdaq.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=saveFiledelib&BZ_PROCS_NO=" + dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "BZ_PROCS_NO");
        tr_File.KeyValue = "JSP(I:pFile=dts_fileList)";
        tr_File.Post();
    }
};
scwin.fn_txbLoad = function() {
    var txbArr = [txb_file_name, txb_file_name2];
    for (var i = 0; i < txbArr.length; i++) {
        txbArr[i].setValue("");
    }
};


//첨부파일 읽기 
scwin.fn_read = function() {
    scwin.fn_txbLoad();
    tr_ReadFile.Action = "/prelistingKosdaq.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readFiledelib&BZ_PROCS_NO=" + dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "BZ_PROCS_NO");
    tr_ReadFile.KeyValue = "JSP(O:pOutput=dts_fileList)";
    tr_ReadFile.Post();
};
scwin.fn_addNewCmt = function() {
    dts_Cmt.insertRow();
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "BZ_PROCS_NO", scwin.strKeyLstBzProcsNo);
    scwin.fn_searchReqInf();

    //fn_setPanWritableOnAdd(pan_Cmt);
    scwin.fn_setKeyCtrOnAdd(); // 추가상태에서는  key컬럼수정가능
    scwin.fn_txbLoad();
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "FORN_COM_FST_LIST_CNTR_CD", '');
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "FORN_COM_SCND_LIST_CNTR_CD", '');
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "FORN_FST_LIST_MISC_CNTR_NM", '');
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "FORN_SCND_LIST_MISC_CNTR_NM", '');
    scwin.fn_setFornListCntrNm();
};
scwin.fn_DeleteRow = function() {
    $c.cp.removeRow(dts_Cmt, dts_Cmt.getRowPosition());
    scwin.fn_save("D");
};
scwin.fn_setKeyCtrOnAdd = function() {
    $c.lc.fn_setCtrWritable([med_ComiteDd]);
};
scwin.fn_setKeyCtrOnUpd = function() {
    $c.lc.fn_setCtrReadOnly([med_ComiteDd]);
};


//파일첨부 head
scwin.fn_setDataHeader = function() {

    //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

};


//파일다운로드	
scwin.fn_filedown = function(attach_seq) {
    location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&file_id=" + dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "BZ_PROCS_NO") + "&attach_seq=" + attach_seq + "&gubun=13";
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
scwin.fn_GetParDtl = function(arrPar) {
    arrPar[0] = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "FORN_COM_FST_LIST_CNTR_CD");
    arrPar[1] = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "FORN_COM_SCND_LIST_CNTR_CD");
    arrPar[2] = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "FORN_FST_LIST_MISC_CNTR_NM");
    arrPar[3] = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "FORN_SCND_LIST_MISC_CNTR_NM");
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParDtl = function(arrPar) {
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "FORN_COM_FST_LIST_CNTR_CD", arrPar[0]);
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "FORN_COM_SCND_LIST_CNTR_CD", arrPar[1]);
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "FORN_FST_LIST_MISC_CNTR_NM", arrPar[2]);
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "FORN_SCND_LIST_MISC_CNTR_NM", arrPar[3]);
    scwin.fn_setFornListCntrNm();
};
scwin.fn_setFornListCntrNm = function() {
    var FORN_COM_FST_LIST_CNTR_CD = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "FORN_COM_FST_LIST_CNTR_CD");
    var FORN_COM_SCND_LIST_CNTR_CD = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "FORN_COM_SCND_LIST_CNTR_CD");
    var FORN_FST_LIST_MISC_CNTR_NM = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "FORN_FST_LIST_MISC_CNTR_NM");
    var FORN_SCND_LIST_MISC_CNTR_NM = dts_Cmt.getCellData(dts_Cmt.getRowPosition(), "FORN_SCND_LIST_MISC_CNTR_NM");
    switch (FORN_COM_FST_LIST_CNTR_CD) {
        case '1':
            FORN_FST_LIST_MISC_CNTR_NM = '중국';
            break;
        case '2':
            FORN_FST_LIST_MISC_CNTR_NM = '일본';
            break;
        case '3':
            FORN_FST_LIST_MISC_CNTR_NM = '미국';
            break;
        default:
            break;
    }
    switch (FORN_COM_SCND_LIST_CNTR_CD) {
        case '1':
            FORN_SCND_LIST_MISC_CNTR_NM = '중국';
            break;
        case '2':
            FORN_SCND_LIST_MISC_CNTR_NM = '일본';
            break;
        case '3':
            FORN_SCND_LIST_MISC_CNTR_NM = '미국';
            break;
        default:
            break;
    }
    $c.stf.setObjectValue(tbx_foreign1, FORN_FST_LIST_MISC_CNTR_NM);
    $c.stf.setObjectValue(tbx_foreign2, FORN_SCND_LIST_MISC_CNTR_NM);
};
scwin.fn_searchIssue = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=PRELISTING_KOSPI_CMTDELIB_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.prelistingkospi.select.cmtdelib.total.issue" + "&{P}param01=" + scwin.strKeyLstBzProcsNo + "&{P}param02=" + scwin.strKeyLstBzProcsNo + "&{P}param03=" + scwin.strKeyLstBzProcsNo;
    dts_Issue.DataID = encodeURI(url);
    dts_Issue.reset();
};
scwin.dts_Cmt_OnLoadCompleted = async function(rowcount) {
    if (dts_Cmt.getTotalRow() > 0) {
        scwin.fn_setKeyCtrOnUpd(); // 조회직후에는 수정상태
        scwin.fn_searchReqInf();
        //fn_fileSearch();
        scwin.fn_read();
    } else {
        if (confirm(scwin.MSG_NO_COMT)) {
            scwin.fn_addNewCmt();
        } else {
            await $c.frame.CloseFrame(); // CloseFrame은 호출자가 있을경우 유효하다.

        }
    }

    /*
    fn_setPanReadOnlyOnLoad(dts_Cmt, pan_Cmt);
    med_ComiteDd.readOnly = true;
    */
};
scwin.dts_Cmt_OnRowPosChanged = function(row) {
    if (dts_Cmt.getTotalRow() > 0) {
        if (dts_Cmt.getCellData(row, "BZ_PROCS_NO") != "") {
            scwin.fn_searchReqInf();
        }

        //alert("fn_fileSearch");
        //fn_fileSearch();
        scwin.fn_read();
        scwin.fn_setFornListCntrNm();
    }
};
scwin.dts_ReqInf_OnLoadCompleted = function(rowcount) {
    if (dts_ReqInf.getCellData('1', 'SECUGRP_ID2') == '1' || dts_ReqInf.getCellData('1', 'SECUGRP_ID3') == '1') {
        $c.stf.showObj(pan_Forn, true);
    } else {
        $c.stf.showObj(pan_Forn, false);
    }
};
scwin.tr_Save_OnFail = function() {
    $c.win.alert(scwin.MSG_TR_FAIL);
};
scwin.tr_Save_OnSuccess = function() {
    $c.win.alert(scwin.MSG_TR_DOME);
    scwin.fn_search();
    scwin.fn_parentRefresh();
};
scwin.img_SetComiteDd_onclick = function() {
    scwin.fn_ShowCalendar(med_ComiteDd);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_Save_onclick = function() {
    scwin.fn_save("I");
};
scwin.img_Regist_onclick = function() {
    scwin.fn_addNewCmt();
};
scwin.img_Delete_onclick = function() {
    scwin.fn_DeleteRow();
};
scwin.btn_lineadd_onclick = function() {
    if (dts_fileList.getCellData(1, "filename") == "") {
        dts_fileList.insertRow();
        inf_find.open();
        if (inf_find.getValue() != "") {
            dts_fileList.setCellData(1, "fileInfo", inf_find.getValue());
            //dts_fileList.NameString(2, "SEQ") = 2;
            file_name.setValue(inf_find.getValue());
            txb_seq.setValue("1");
            txb_file_name.setValue(inf_find.getValue());
        } else {
            $c.cp.removeRow(dts_fileList, 1);
            txb_file_name.setValue("");
        }
    }
};
scwin.btn_lineadd2_onclick = function() {
    if (dts_fileList.getCellData(2, "filename") == "") {
        dts_fileList.insertRow();
        inf_find.open();
        if (inf_find.getValue() != "") {
            dts_fileList.setCellData(2, "fileInfo", inf_find.getValue());
            //dts_fileList.NameString(2, "SEQ") = 2;
            file_name.setValue(inf_find.getValue());
            txb_seq.setValue("2");
            txb_file_name2.setValue(inf_find.getValue());
        } else {
            $c.cp.removeRow(dts_fileList, 2);
            txb_file_name2.setValue("");
        }
    }
};
scwin.btn_linedelete_onclick = function() {
    for (var j = 1; j < dts_fileList.getTotalRow() + 1; j++) {
        if (dts_fileList.getCellData(j, "SEQ") == 1) {
            $c.cp.removeRow(dts_fileList, j);
            //dts_fileList.NameString(2, "SEQ") = 2;		
            txb_file_name.setValue("");
            scwin.file_flag = "Y";
            break;
        }
    }
};
scwin.btn_linedelete2_onclick = function() {
    for (var j = 1; j < dts_fileList.getTotalRow() + 1; j++) {
        if (dts_fileList.getCellData(j, "SEQ") == 2) {
            $c.cp.removeRow(dts_fileList, j);
            //dts_fileList.NameString(2, "SEQ") = 2;		
            txb_file_name2.setValue("");
            scwin.file_flag = "Y";
            break;
        }
    }
};
scwin.inf_find_OnClick = function() {
    /*
       var filenm = file_name.value;

    dts_fileList.setNameString(dts_fileList.rowposition, "fileInfo",inf_find.Value) ;
    	file_name.value = inf_find.Value;	
    	//dts_fileList.NameString(dts_fileList.rowposition, "SEQ") = "";	

    	if(inf_find.Value == ""){
    		file_name.value = filenm;
    	}
    */
};
scwin.btn_fileSave_onclick = function() {
    if (dts_fileList.getRowStatus(1) == 0 && dts_fileList.getCellData(1, "filename") != "") {
        scwin.fn_filedown("1");
    }
};
scwin.btn_fileSave2_onclick = function() {
    if (dts_fileList.getRowStatus(2) == 0 && dts_fileList.getCellData(2, "filename") != "") {
        scwin.fn_filedown("2");
    }
};
scwin.tr_File_OnFail = function() {
    $c.win.alert(scwin.MSG_TR_FAIL);
};
scwin.tr_File_OnSuccess = function() {
    $c.win.alert(scwin.MSG_TR_DOME);
    scwin.fn_search();
};
scwin.dts_fileList_OnLoadCompleted = function(rowcount) {
    var setArr = [txb_file_name, txb_file_name2];
    //var setBtn = [btn_lineadd,btn_lineadd2,btn_lineadd3,btn_lineadd4];
    if (rowcount > 0) {
        var k;
        for (var i = 0; i < rowcount; i++) {
            k = dts_fileList.getCellData(i + 1, "SEQ");
            if (k >= '3') {
                continue;
            }
            setArr[k - 1].setValue(dts_fileList.getCellData(i + 1, "filename"));
        }
    }
};
scwin.dts_fileList_OnLoadError = function() {

};
scwin.gform_onload = function() {
    var arr = new Array();
    scwin.fn_searchCode();
    scwin.fn_GetPar = $c.frame.path("../").scwin.fn_GetPar;
    scwin.fn_SetPar = $c.frame.path("../").scwin.fn_SetPar;
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(arr);
    }
    /* 
    arr[0] = "03929";
    arr[1] = "920";
    arr[2] = "시험발행기관명";
    */

    $c.stf.showObj(panel_Term, false);
    txb_IsurCd.setValue((arr.length >= 1 ? arr[0] : ""));
    scwin.strKeyIsurCd = (arr.length >= 1 ? arr[0] : "");
    scwin.strKeyLstBzProcsNo = (arr.length >= 2 ? arr[1] : "");
    txb_CoNm.setValue((arr.length >= 3 ? arr[2] : "")); // 발행기관명도 넘겨받아 컨트롤에 반영해야 한다.

    if (arr.length > 2) {
        scwin.fn_search();
    }
    scwin.fn_setDataHeader();
    scwin.fn_setFornListCntrNm();
    scwin.fn_searchIssue();
};
